code='''def transform(grid):
    # Locate the hollow rectangle whose top and bottom rows contain only its sides.
    # Fill its hollow rows with the matching solid rectangles elsewhere in the grid.
    from collections import deque
    h,w=len(grid),len(grid[0])
    bg=max(set(v for row in grid for v in row),key=lambda v:sum(r.count(v) for r in grid))
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg or (r,c) in seen: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((color,cells))
    frames=[]; fillers=[]
    for color,cells in comps:
        rs=[x[0] for x in cells]; cs=[x[1] for x in cells]
        r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        H,W=r1-r0+1,c1-c0+1
        shape={(r-r0,c-c0) for r,c in cells}
        if len(shape)==H*W:
            fillers.append((color,r0,c0,H,W))
        if H>=3 and W>=3:
            expected=set()
            for rr in range(H):
                if rr==H//2: expected|={(rr,cc) for cc in range(W)}
                else: expected|={(rr,0),(rr,W-1)}
            if shape==expected: frames.append((color,r0,c0,H,W))
    color,r0,c0,H,W=frames[0]
    out=[[bg]*W for _ in range(H)]
    for rr in range(H):
        for cc in range(W):
            if grid[r0+rr][c0+cc]==color: out[rr][cc]=color
    for rr in range(H):
        if all(grid[r0+rr][c0+cc]==bg for cc in range(1,W-1)):
            matches=[f for f in fillers if f[3]==sum(grid[r0+k][c0+1]==bg for k in range(H) if all(grid[r0+k][c0+cc]==bg for cc in range(1,W-1))) and f[4]==W-2]
            # Use exact height-1 or stacked height-N filler, consuming each once.
    unused=list(fillers)
    hollow=[rr for rr in range(H) if all(grid[r0+rr][c0+cc]==bg for cc in range(1,W-1))]
    groups=[]
    for rr in hollow:
        if not groups or rr!=groups[-1][-1]+1: groups.append([rr])
        else: groups[-1].append(rr)
    for group in groups:
        match=next(f for f in unused if f[3]==len(group) and f[4]==W-2)
        unused.remove(match)
        fc,fr,fcol,fh,fw=match
        for i,rr in enumerate(group):
            for cc in range(1,W-1): out[rr][cc]=fc
    return out
